const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

// Implements the Source/Lease contract from src/source.ts, with call tracking.
function fixture({ values = ['a', 'b', null], readError, closeError, mapper } = {}) {
  const calls = { opens: 0, reads: 0, closes: 0 };
  const source = {
    async open() {
      calls.opens++;
      return {
        async read() {
          calls.reads++;
          if (readError) throw readError;
          return values.shift();
        },
        async close() {
          calls.closes++;
          if (closeError) throw closeError;
        },
      };
    },
  };
  return { calls, stream: new EventService(source, mapper).stream() };
}

// Identity checks also cover thrown undefined, which assert.rejects cannot match.
async function rejectsWith(action, expected) {
  let rejected = false;
  try {
    await action();
  } catch (error) {
    rejected = true;
    assert.equal(error, expected);
  }
  assert.equal(rejected, true, 'expected rejection');
}

async function main() {
  {
    const { calls, stream } = fixture();
    assert.deepEqual(calls, { opens: 0, reads: 0, closes: 0 });
    await stream.return();
    assert.deepEqual(calls, { opens: 0, reads: 0, closes: 0 });
  }
  {
    const { calls, stream } = fixture();
    assert.deepEqual(await stream.next(), { value: 'A', done: false });
    assert.deepEqual(calls, { opens: 1, reads: 1, closes: 0 });
    assert.deepEqual(await stream.next(), { value: 'B', done: false });
    assert.deepEqual(calls, { opens: 1, reads: 2, closes: 0 });
    assert.deepEqual(await stream.next(), { value: undefined, done: true });
    await stream.next();
    await stream.return();
    assert.deepEqual(calls, { opens: 1, reads: 3, closes: 1 });
  }
  for (const exit of ['exhaustion', 'break', 'return', 'read', 'mapper', 'throw']) {
    for (const closeFails of [false, true]) {
      const primary = new Error(exit);
      const closeError = closeFails ? new Error('close') : undefined;
      const { calls, stream } = fixture({
        values: exit === 'exhaustion' ? [null] : ['a', 'b', null],
        readError: exit === 'read' ? primary : undefined,
        mapper: exit === 'mapper' ? () => { throw primary; } : undefined,
        closeError,
      });
      const action = async () => {
        if (exit === 'break') {
          for await (const value of stream) {
            assert.equal(value, 'A');
            break;
          }
        } else if (exit === 'return' || exit === 'throw') {
          await stream.next();
          if (exit === 'return') await stream.return();
          else await stream.throw(primary);
        } else {
          await stream.next();
        }
      };
      const hasPrimary = ['read', 'mapper', 'throw'].includes(exit);
      if (hasPrimary || closeFails) {
        await rejectsWith(action, hasPrimary ? primary : closeError);
      } else {
        await action();
      }
      await stream.next();
      await stream.return();
      assert.deepEqual(calls, { opens: 1, reads: 1, closes: 1 }, `${exit}, closeFails=${closeFails}`);
    }
  }
  {
    const closeError = new Error('close');
    const { calls, stream } = fixture({ closeError });
    await stream.next();
    await rejectsWith(() => stream.throw(undefined), undefined);
    assert.equal(calls.closes, 1);
  }
  {
    const openError = new Error('open');
    let opens = 0;
    const stream = new EventService({ async open() { opens++; throw openError; } }).stream();
    assert.equal(opens, 0);
    await rejectsWith(() => stream.next(), openError);
    await stream.return();
    assert.equal(opens, 1);
  }
}

module.exports = main();

